WITH joined AS (SELECT e.id, e.email, e.dept_id, e.manager_id, e.hire_date, e.level, p.full_name AS employee_full_name, p.level AS employee_level FROM employees e LEFT JOIN employees p ON e.manager_id = p.id) SELECT s.id, s.email, s.dept_id, s.manager_id, s.hire_date, s.level, s.employee_full_name, s.employee_level, (SELECT SUM(e2.salary) FROM employees e2 WHERE e2.manager_id = s.manager_id) AS sum_employee_salary FROM joined s ORDER BY level ASC NULLS FIRST;
